// Helper: get service by slug
export function getServiceBySlug(slug) {
  return SERVICES.find(s => s.slug === slug);
}

// Helper: get services by category
export function getServicesByCategory(categoryId) {
  return SERVICES.filter(s => s.category === categoryId);
}

// Helper: get related services data
export function getRelatedServices(slugs) {
  return SERVICES.filter(s => slugs.includes(s.slug));
}

// Helper: get category by id
export function getCategoryById(id) {
  return SERVICE_CATEGORIES.find(c => c.id === id);
}

// Helper: get all slugs (for generateStaticParams)
export function getAllServiceSlugs() {
  return SERVICES.map(s => ({ slug: s.slug }));
}
